CREATE TABLE production_history_epoch(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
INSERT INTO production_history_epoch VALUES(1,0);
CREATE TRIGGER production_history_matches_insert AFTER INSERT ON matches WHEN NEW.status='finished' BEGIN UPDATE production_history_epoch SET version=version+1 WHERE id=1; END;
CREATE TRIGGER production_history_stats_insert AFTER INSERT ON match_statistics WHEN 1 BEGIN UPDATE production_history_epoch SET version=version+1 WHERE id=1; END;
CREATE TRIGGER production_history_matches_update AFTER UPDATE ON matches WHEN (OLD.status='finished' OR NEW.status='finished') AND (OLD.status IS NOT NEW.status OR OLD.final_home_goals IS NOT NEW.final_home_goals OR OLD.final_away_goals IS NOT NEW.final_away_goals OR OLD.kickoff_at IS NOT NEW.kickoff_at OR OLD.home_team_id IS NOT NEW.home_team_id OR OLD.away_team_id IS NOT NEW.away_team_id) BEGIN UPDATE production_history_epoch SET version=version+1 WHERE id=1; END;
CREATE TRIGGER production_history_stats_update AFTER UPDATE ON match_statistics WHEN OLD.home_shots IS NOT NEW.home_shots OR OLD.away_shots IS NOT NEW.away_shots OR OLD.home_shots_on_target IS NOT NEW.home_shots_on_target OR OLD.away_shots_on_target IS NOT NEW.away_shots_on_target OR OLD.home_corners IS NOT NEW.home_corners OR OLD.away_corners IS NOT NEW.away_corners OR OLD.home_fouls IS NOT NEW.home_fouls OR OLD.away_fouls IS NOT NEW.away_fouls OR OLD.home_yellow_cards IS NOT NEW.home_yellow_cards OR OLD.away_yellow_cards IS NOT NEW.away_yellow_cards OR OLD.home_red_cards IS NOT NEW.home_red_cards OR OLD.away_red_cards IS NOT NEW.away_red_cards BEGIN UPDATE production_history_epoch SET version=version+1 WHERE id=1; END;
CREATE TRIGGER production_history_matches_delete AFTER DELETE ON matches WHEN OLD.status='finished' BEGIN UPDATE production_history_epoch SET version=version+1 WHERE id=1; END;
CREATE TRIGGER production_history_stats_delete AFTER DELETE ON match_statistics WHEN 1 BEGIN UPDATE production_history_epoch SET version=version+1 WHERE id=1; END;
